export function boundedItems(items,maxBytes=16000) {
 if(!Array.isArray(items))throw new TypeError("items");
 if(!Number.isInteger(maxBytes)||maxBytes<2)throw new RangeError("maxBytes");
 const out=[];let bytes=2;
 for(const item of items){const n=JSON.stringify(item).length;if(bytes+n>maxBytes)break;out.push(item);bytes+=n;}
 return out;
}

